def test_setlang_preserves_http_referer_query_string(self):
    encoded_url = '/test-setlang/x/?parameter=some%20%26%20thing'
    lang_code = self._get_inactive_language_code()
    for post_data in ({}, {'next': ''}, {'language': lang_code}):
        with self.subTest(post_data=post_data):
            response = self.client.post(
                '/i18n/setlang/', post_data, HTTP_REFERER=encoded_url,
            )
            self.assertEqual(response.status_code, 302)
            self.assertEqual(response.url, encoded_url)

